import styled from 'styled-components';

import { Box, BoxProps } from '@openfin/ui-library';

import { IconContainer } from './Icons';
import { ResultContainer } from './Result';

const PLACEHOLDER_LENGTHS = [
    { text: 300, subtext: 207 },
    { text: 262, subtext: 116 },
    { text: 156, subtext: 56 },
    { text: 210, subtext: 130 }
];

const SkeletonIconContainer = styled(IconContainer)`
    background: var(--color-enterprise-skeleton-loader-background);
`;

export const SkeletonResultList = ({ resultsNum }: { resultsNum: number }) => {
    return (
        <>
            {Array.from({ length: resultsNum }).map((_, index) => (
                <SkeletonResult variant={index % 4} key={`skeleton-result-${index}`} />
            ))}
        </>
    );
};

export const SkeletonResult: React.FC<{ variant: number }> = ({ variant }) => {
    return (
        <ResultContainer>
            <SkeletonIconContainer />
            <TextPlaceholderContainer>
                <TextPlaceholder
                    className="skeleton-result-text-placeholder"
                    width={PLACEHOLDER_LENGTHS[variant].text}
                />
                <TextPlaceholder
                    className="skeleton-result-text-placeholder"
                    width={PLACEHOLDER_LENGTHS[variant].subtext}
                />
            </TextPlaceholderContainer>
        </ResultContainer>
    );
};

const TextPlaceholderContainer = styled(Box)`
    height: ${({ theme }) => theme.px.xxlarge};

    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: flex-start;
`;

const TextPlaceholder = styled(Box)<BoxProps & { width: number }>`
    height: ${({ theme }) => theme.px.small};
    width: ${({ width }) => width}px;

    border-radius: 3px;
    background: var(--color-enterprise-skeleton-loader-background);

    background: linear-gradient(
        45deg,
        var(--color-enterprise-skeleton-loader-template-start) 0%,
        var(--color-enterprise-skeleton-loader-template-middle) 50%,
        var(--color-enterprise-skeleton-loader-template-end) 100%
    );
    background-size: 200% 200%;
    animation: shimmer 3s linear infinite;

    @keyframes shimmer {
        0% {
            background-position: 200% 0;
        }
        100% {
            background-position: -200% 0;
        }
    }
`;
