import { MutableRefObject, useCallback, useContext, useEffect } from 'react';

import type OpenFin from '@openfin/core';

import { SearchMenuChannelResponse } from '@common/utils/popup-window';

import { ActionedSite } from '@client-platform/shapes';
import { DEFAULT_ALL_TAB, SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';

/**
 * Custom hook that sends messages to the browser window about either which site has been selected for navigation or what key has been
 * pressed while focused in the search results view to enable continued modification of the search text while focused inside the view.
 *
 * @param searchMenuChannel - Ref object for the broadcast channel used to communicate with the browser window.
 * @param selectedSite - The site selected by the user to navigate to.
 * @param selectedViews - Array of currently selected views in the browser window.
 * @param shouldShowEmptySearchContainer - Boolean indicating whether the empty search container is currently being shown.
 * @param hasTextChangedSinceExpansion - Boolean indicating whether user has modified the URL since search menu expanded.
 * @returns Object containing a function to send keyboard events to the browser window.
 */
const usePostMessageToBrowserWindow = (
    searchMenuChannel: MutableRefObject<BroadcastChannel>,
    selectedSite: ActionedSite,
    selectedViews: OpenFin.Identity[],
    shouldShowEmptySearchContainer: boolean,
    hasTextChangedSinceExpansion: MutableRefObject<boolean>
) => {
    const { isQueryingResults, activeProviderId } = useContext(SearchResultsContext);

    useEffect(() => {
        // Only launch selected site if we've finished querying or we are launching from the empty search container apps
        if (
            searchMenuChannel.current &&
            (!isQueryingResults || shouldShowEmptySearchContainer) &&
            selectedSite !== undefined
        ) {
            searchMenuChannel.current.postMessage({
                type: 'search-response',
                selectedSite,
                selectedView: selectedViews[0],
                trigger: selectedSite?.action,
                handled: false
            } as SearchMenuChannelResponse);
        }
        // We do not want to post a message every time the selectedViews change so remove selectedViews from dep array
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedSite]);

    useEffect(() => {
        // Informs browser window that search provider tab has been activated if a user has not modified the text
        // Will trigger the browser window to clear the address bar
        if (
            searchMenuChannel.current &&
            activeProviderId !== DEFAULT_ALL_TAB.id &&
            !hasTextChangedSinceExpansion.current
        ) {
            searchMenuChannel.current.postMessage({ type: 'search-provider-changed' });
        }
    }, [activeProviderId]);

    const sendKeyboardEventToBrowserWindow = useCallback(
        (event: React.KeyboardEvent) => {
            if (searchMenuChannel.current) {
                const { type, key, metaKey, ctrlKey, altKey } = event;
                searchMenuChannel.current.postMessage({
                    type: 'keyboard-event',
                    keyboardEvent: {
                        type,
                        options: {
                            key,
                            metaKey,
                            ctrlKey,
                            altKey
                        }
                    }
                } as SearchMenuChannelResponse);
            }
        },
        [searchMenuChannel]
    );

    return { sendKeyboardEventToBrowserWindow };
};

export default usePostMessageToBrowserWindow;
