import { getCurrentSync } from '@client-platform/api';
import { SearchProvider, SearchProviderResult, SearchSitesRequest, SearchSitesResponse } from '@client-platform/shapes';

export const searchSites = async (searchRequest: SearchSitesRequest): Promise<SearchSitesResponse> => {
    const platform = getCurrentSync();
    const view = fin.View.wrapSync(fin.me.identity);
    const browserWindow = platform.Browser.wrapSync((await view.getCurrentWindow()).identity);
    // eslint-disable-next-line no-underscore-dangle
    return await browserWindow._searchSites(searchRequest);
};

export const getSearchProviders = async (): Promise<SearchProvider[]> => {
    const platform = getCurrentSync();
    const view = fin.View.wrapSync(fin.me.identity);
    const browserWindow = platform.Browser.wrapSync((await view.getCurrentWindow()).identity);
    // eslint-disable-next-line no-underscore-dangle
    return await browserWindow._getSearchProviders();
};

export interface AsyncResultsObserver {
    on: (callback: (payload: SearchProviderResult) => void) => void;
    off: (callback: (payload: SearchProviderResult) => void) => void;
}
