import { useContext, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';

import debounce from 'lodash.debounce';

import { SearchProvider, SearchProviderResult } from '@client-platform/shapes';
import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';
import { SEARCH_DEBOUNCE_MS } from '@enterprise/hooks/EnterpriseSearchMenu/useInitChannelToBrowserWindow';

type LazyLoadingReturn = {
    isLoading: boolean;
    providerResults?: SearchProviderResult['results'];
};

/**
 * Custom hook that announces single provider search results status to the browser window.
 * Monitors search state, lazy loading, and pagination to post accessibility announcements via BroadcastChannel.
 *
 * @param providerResults - The current provider results
 * @param activeProvider - The active search provider
 * @param lazyLoading - The lazy loading state from useLazyLoading hook (can be undefined)
 */
export const useSingleProviderAnnounceMessages = (
    providerResults: SearchProviderResult,
    activeProvider: SearchProvider | undefined,
    lazyLoading: LazyLoadingReturn | undefined
) => {
    const { t } = useTranslation();
    const { isQueryingResults } = useContext(SearchResultsContext);
    const { searchQuery, queryId, postSingleProviderAnnouncement } = useContext(SearchMenuControlContext);
    const previousQueryIdRef = useRef<string | undefined>(undefined);
    const previousResultsCountRef = useRef<number>(0);
    const isInitialLoadRef = useRef<boolean>(true);
    const hasAnnouncedNoResultsRef = useRef<boolean>(false);

    const providerName = activeProvider?.title || 'provider';

    // Get current results count
    const resultsCount = useMemo(() => {
        return lazyLoading?.providerResults?.length || providerResults?.results?.length || 0;
    }, [lazyLoading?.providerResults, providerResults?.results]);

    // Detect if this is initial load vs pagination
    const isInitialLoad = useMemo(() => {
        // If queryId changed, it's a new search (initial load)
        if (queryId !== previousQueryIdRef.current && queryId) {
            isInitialLoadRef.current = true;
            return true;
        }
        // If we have no results yet, it's initial load
        if (resultsCount === 0) {
            return true;
        }
        // If results count decreased, it's a new search (initial load)
        if (resultsCount < previousResultsCountRef.current) {
            isInitialLoadRef.current = true;
            return true;
        }
        // Otherwise, it's pagination
        return false;
    }, [queryId, resultsCount]);

    // Track when initial load completes
    useEffect(() => {
        if (!isInitialLoad && isInitialLoadRef.current) {
            isInitialLoadRef.current = false;
        }
    }, [isInitialLoad]);

    // Debounced function to announce "Searching" message
    // This aligns with when the search actually executes (after debounce delay)
    const announceSearching = useRef(
        debounce(
            (query: string, provider: string) => {
                const message = t('searchResults.searchingProvider', { providerName: provider, query });
                postSingleProviderAnnouncement(message);
            },
            SEARCH_DEBOUNCE_MS,
            { leading: false, trailing: true }
        )
    ).current;

    // Track queryId changes to detect when search is actually executing
    useEffect(() => {
        // Only announce "Searching" when queryId changes (indicating search has been initiated)
        // and isQueryingResults is true
        if (queryId !== previousQueryIdRef.current && queryId && isQueryingResults) {
            const query = searchQuery.current?.trim() || '';
            if (query) {
                announceSearching(query, providerName);
            }
            previousQueryIdRef.current = queryId;
            previousResultsCountRef.current = 0; // Reset count for new search
            isInitialLoadRef.current = true;
            // Reset no results announcement flag when starting a new search
            hasAnnouncedNoResultsRef.current = false;
        } else if (!queryId) {
            // Reset previous queryId when queryId is cleared
            previousQueryIdRef.current = undefined;
            announceSearching.cancel();
            hasAnnouncedNoResultsRef.current = false;
        }
    }, [queryId, isQueryingResults, searchQuery, providerName, announceSearching]);

    // Handle loading states
    useEffect(() => {
        // Skip if we're still querying (handled by queryId tracking above)
        if (isQueryingResults) return;

        const isLoading = lazyLoading?.isLoading || !providerResults?.results;
        const hasResults = resultsCount > 0;

        let message = '';

        if (isLoading && !hasResults) {
            // Initial loading state - no results yet
            message = t('searchResults.loadingProviderResults', { providerName });
        } else if (isLoading && hasResults && !isInitialLoadRef.current) {
            // Pagination loading - we already have results
            message = t('searchResults.loadingMoreProviderResults', { providerName });
        } else if (!isLoading && hasResults) {
            // Results available (either initial load completed or pagination completed)
            if (resultsCount !== previousResultsCountRef.current) {
                message = t('searchResults.providerResultsAvailable', { providerName, count: resultsCount });
                previousResultsCountRef.current = resultsCount;
            }
        }

        if (message) {
            postSingleProviderAnnouncement(message);
        }
    }, [
        isQueryingResults,
        lazyLoading?.isLoading,
        providerResults?.results,
        resultsCount,
        providerName,
        t,
        postSingleProviderAnnouncement
    ]);

    // Handle "no results" announcement separately
    useEffect(() => {
        // Skip if we're still querying
        if (isQueryingResults) return;

        const isLoading = lazyLoading?.isLoading || !providerResults?.results;
        const hasNoResults = !isLoading && resultsCount === 0;
        const query = searchQuery.current?.trim() || '';

        if (hasNoResults && !hasAnnouncedNoResultsRef.current && query) {
            // Only announce if we haven't already announced no results for this search
            const message = t('searchResults.noResultsFoundProvider', { providerName, query });
            postSingleProviderAnnouncement(message);
            hasAnnouncedNoResultsRef.current = true;
        } else if (!hasNoResults) {
            // Reset flag when results appear
            hasAnnouncedNoResultsRef.current = false;
        }
    }, [
        isQueryingResults,
        lazyLoading?.isLoading,
        providerResults?.results,
        resultsCount,
        providerName,
        searchQuery,
        t,
        postSingleProviderAnnouncement
    ]);
};
