import { useEffect, useState } from 'react';

import type OpenFin from '@openfin/core';

import { formatUrl } from '@common/utils/enterpriseBrowser';

/**
 * Custom hook to determine if a specific tab is open and to get the view to switch to.
 *
 * @param {OpenFin.Identity[]} openViews - The list of currently open views.
 * @param {{ url: string }} siteInfo - An object containing the URL of the site.
 * @param {boolean} isSiteAppOrWebsite - A flag indicating if the site is an app or a website.
 * @param {OpenFin.Identity[]} [selectedViews] - An optional list of views that are currently selected.
 * @returns {{ isTabOpen: boolean; viewToSwitchTo: OpenFin.Identity }} - An object containing a boolean indicating if the tab is open and the view to switch to.
 */
const useIsTabOpen = (
    openViews: OpenFin.Identity[],
    siteInfo: { url: string },
    isSiteAppOrWebsite: boolean,
    selectedViews?: OpenFin.Identity[]
): { isTabOpen: boolean; viewToSwitchTo: OpenFin.Identity } => {
    const [isTabOpen, setIsTabOpen] = useState<boolean>(false);
    const [viewToSwitchTo, setViewToSwitchTo] = useState<OpenFin.Identity | undefined>(undefined);

    useEffect(() => {
        const checkTabs = async () => {
            for (const openView of openViews) {
                // TODO - move this up to openViews - otherwise calling getinfo on every view for every result!
                const options = await fin.View.wrapSync(openView).getInfo();
                if (
                    isSiteAppOrWebsite &&
                    formatUrl(options.url) === formatUrl(siteInfo.url) &&
                    !selectedViews?.some((identity) => identity.name === openView.name)
                ) {
                    setIsTabOpen(true);
                    setViewToSwitchTo(openView);
                    break;
                }
            }
        };

        checkTabs();
    }, [openViews, siteInfo, selectedViews, isSiteAppOrWebsite]);

    return { isTabOpen, viewToSwitchTo };
};

export default useIsTabOpen;
