import { SearchProvider } from '@client-platform/shapes';
import { DEFAULT_ALL_TAB } from '@enterprise/context/SearchMenu/SearchResultsContext';

export type QuerylessState = {
    showQuerylessText: boolean;
    showEmptyContainer: boolean;
};

export const getQuerylessState = (
    query: string,
    hasTextChangedSinceExpansion: boolean,
    provider: SearchProvider
): QuerylessState => {
    // If on provider tab and query is empty or has been modified by user
    if ((query.length === 0 || !hasTextChangedSinceExpansion) && provider) {
        if (provider.id === DEFAULT_ALL_TAB.id) {
            return { showQuerylessText: false, showEmptyContainer: true };
        } else {
            // for those support queryless providers
            if (provider.supportsQueryless) {
                return { showQuerylessText: false, showEmptyContainer: false };
            } else {
                // for those not support queryless providers, need to show a text
                return { showQuerylessText: true, showEmptyContainer: true };
            }
        }
    } else {
        return { showQuerylessText: false, showEmptyContainer: false };
    }
};
