import React, { useCallback, useContext, useEffect, useRef, useState } from 'react';

import styled from 'styled-components';

import { enterpriseSearchMenuTestIds } from '@common/utils/test-ids';

import { CommandBar } from '@enterprise/components/ControlBar/SearchMenu/CommandBar';

import { Site, SiteAction } from '@client-platform/shapes';
import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import useKeyboardNavigation from '@enterprise/hooks/EnterpriseSearchMenu/useKeyboardNavigation';

export type ViewMoreButton = { type: 'view-more-result'; id: string; providerId: string };

export const RESULTS_CONTAINER_ID = 'results-container';

export type SelectableResult = Site | ViewMoreButton;

export interface ResultsContainerWrapperProps {
    isLoading: boolean;
    children: (
        setFocused: (toFocus: SelectableResult) => void,
        focused: SelectableResult,
        onSiteAction: (site: Site, action: SiteAction) => void
    ) => React.ReactNode;
    flattenedResults: SelectableResult[] | [];
}

export const ResultsContainerWrapper = (props: ResultsContainerWrapperProps) => {
    const { setSelectedSite, sendKeyboardEventToBrowserWindow } = useContext(SearchMenuControlContext);

    const resultListContainer = useRef<HTMLDivElement>(null);
    const [focused, setFocused] = useState<SelectableResult | null>();

    const onSiteAction = useCallback(
        (site: Site, action: SiteAction) => {
            setFocused(site);
            setSelectedSite({ ...site, action });
        },
        [props]
    );

    useKeyboardNavigation(
        focused,
        setFocused,
        props.flattenedResults,
        (site: Site) => setFocused(site),
        sendKeyboardEventToBrowserWindow,
        resultListContainer.current
    );

    useEffect(() => {
        if (!props.flattenedResults) {
            return;
        }
        if (!focused) {
            resultListContainer.current?.setAttribute('aria-activedescendant', focused?.id ?? '');
        } else if (props.flattenedResults.length > 0) {
            resultListContainer.current?.setAttribute('aria-activedescendant', props.flattenedResults[0].id);
        } else {
            setFocused(null);
        }
    }, [props.flattenedResults, focused]);

    useEffect(() => {
        // Enables auto focus of first result after all results have loaded and user hasn't yet focused on one
        if (!props.isLoading && props.flattenedResults.length && !focused) {
            setFocused(props.flattenedResults[0]);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [props.isLoading, props.flattenedResults.length]);

    return (
        <Container>
            <ScrollableArea className="search-results-scrollable-area">
                <ContentContainer
                    role="application"
                    ref={resultListContainer}
                    aria-activedescendant=""
                    id={RESULTS_CONTAINER_ID}
                    data-testid={enterpriseSearchMenuTestIds.resultsContainer}
                >
                    {props.children(setFocused, focused, onSiteAction)}
                </ContentContainer>
            </ScrollableArea>
            <CommandBar isLoading={props.isLoading} selectedResult={focused} />
        </Container>
    );
};

const Container = styled.div`
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
`;

const ScrollableArea = styled.div`
    border-left: 1px solid var(--color-enterprise-search-menu-border);
    border-right: 1px solid var(--color-enterprise-search-menu-border);

    ::-webkit-scrollbar {
        display: none;
    }

    user-select: none;
    width: 100%;
    flex: 1;
    overflow: auto;
`;

const ContentContainer = styled.div`
    padding: 0px ${({ theme }) => theme.px.small} ${({ theme }) => theme.px.small} ${({ theme }) => theme.px.small};
`;
