import { useContext, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';

import debounce from 'lodash.debounce';

import { SearchSitesResponse } from '@client-platform/shapes';
import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';
import { SEARCH_DEBOUNCE_MS } from '@enterprise/hooks/EnterpriseSearchMenu/useInitChannelToBrowserWindow';

import { isContentLoading } from './AllProvidersResultsContainer';

/**
 * Custom hook that announces search results status to the browser window.
 * Monitors search state and posts accessibility announcements via BroadcastChannel.
 *
 * @param flattenedResults - Array of flattened search results
 * @param asyncResults - Array of provider results with loading states
 */
export const useAllProvidersAnnounceMessages = (flattenedResults: unknown[], asyncResults: SearchSitesResponse) => {
    const { t } = useTranslation();
    const { isQueryingResults } = useContext(SearchResultsContext);
    const { searchQuery, queryId, postAllProvidersAnnouncement } = useContext(SearchMenuControlContext);
    const previousQueryIdRef = useRef<string | undefined>(undefined);
    const hasAnnouncedNoResultsRef = useRef<boolean>(false);

    // Calculate if some providers are still loading
    const hasLoadingProviders = useMemo(
        () => !isQueryingResults && asyncResults.some(isContentLoading),
        [isQueryingResults, asyncResults]
    );

    // Calculate if all providers have finished loading
    const allProvidersLoaded = useMemo(
        () => !isQueryingResults && asyncResults.every((provider) => !isContentLoading(provider)),
        [isQueryingResults, asyncResults]
    );

    // Count actual results (excluding view-more buttons)
    const resultsCount = useMemo(() => {
        return flattenedResults.filter((result) => {
            if (result && typeof result === 'object' && 'type' in result) {
                return result.type !== 'view-more-result';
            }
            return true;
        }).length;
    }, [flattenedResults]);

    // Debounced function to announce "Searching for" message
    // This aligns with when the search actually executes (after debounce delay)
    const announceSearching = useRef(
        debounce(
            (query: string) => {
                const message = t('searchResults.searchingFor', { query });
                postAllProvidersAnnouncement(message);
            },
            SEARCH_DEBOUNCE_MS,
            { leading: false, trailing: true }
        )
    ).current;

    // Track queryId changes to detect when search is actually executing
    useEffect(() => {
        // Only announce "Searching for" when queryId changes (indicating search has been initiated)
        // and isQueryingResults is true
        if (queryId !== previousQueryIdRef.current && queryId && isQueryingResults) {
            const query = searchQuery.current?.trim() || '';
            if (query) {
                announceSearching(query);
            }
            previousQueryIdRef.current = queryId;
            // Reset no results announcement flag when starting a new search
            hasAnnouncedNoResultsRef.current = false;
        } else if (!queryId) {
            // Reset previous queryId when queryId is cleared
            previousQueryIdRef.current = undefined;
            announceSearching.cancel();
            hasAnnouncedNoResultsRef.current = false;
        }
    }, [queryId, isQueryingResults, searchQuery, announceSearching]);

    // Generate announcement messages for results (not searching state)
    useEffect(() => {
        // Skip if we're still querying (handled by queryId tracking above)
        if (isQueryingResults) return;

        let message = '';

        if (allProvidersLoaded && resultsCount > 0) {
            // State 3: All results available
            message = t('searchResults.allResultsAvailable', { count: resultsCount });
        } else if (hasLoadingProviders && resultsCount > 0) {
            // State 2: Results available but some providers still loading
            message = t('searchResults.resultsAvailableLoading', { count: resultsCount });
        }

        if (message) {
            postAllProvidersAnnouncement(message);
        }
    }, [isQueryingResults, allProvidersLoaded, hasLoadingProviders, resultsCount, t, postAllProvidersAnnouncement]);

    // Handle "no results" announcement separately
    useEffect(() => {
        // Skip if we're still querying
        if (isQueryingResults) return;

        // Check if all providers have finished loading and there are no results
        const hasNoResults = allProvidersLoaded && resultsCount === 0;
        const query = searchQuery.current?.trim() || '';

        if (hasNoResults && !hasAnnouncedNoResultsRef.current && query) {
            // Only announce if we haven't already announced no results for this search
            const message = t('searchResults.noResultsFoundAllProviders', { query });
            postAllProvidersAnnouncement(message);
            hasAnnouncedNoResultsRef.current = true;
        } else if (!hasNoResults) {
            // Reset flag when results appear
            hasAnnouncedNoResultsRef.current = false;
        }
    }, [isQueryingResults, allProvidersLoaded, resultsCount, searchQuery, t, postAllProvidersAnnouncement]);
};
