import { useEffect, useState } from 'react';

import debounce from 'lodash.debounce';

import { getCurrentSync } from '@client-platform/api';
import { AttachedPage } from '@client-platform/shapes';

/**
 * A custom hook that manages the state of open pages in the application.
 * It fetches the currently attached pages and updates the page state accordingly.
 *
 * @returns An array of currently open pages.
 */
const useOpenPages = (): AttachedPage[] => {
    const [openPages, setOpenPages] = useState<AttachedPage[]>([]);
    useEffect(() => {
        const updateOpenPages = async () => {
            const pages = await getCurrentSync().Browser.getAllAttachedPages();
            setOpenPages(pages);
        };
        const debouncedUpdateOpenPages = debounce(updateOpenPages, 500, { leading: false, trailing: true });
        const ofApp = fin.Application.getCurrentSync();
        ofApp.on('window-layout-ready', debouncedUpdateOpenPages);
        // Replace with better event after CORE-1681
        ofApp.on('window-view-detached', debouncedUpdateOpenPages);

        updateOpenPages();
        return () => {
            ofApp.removeListener('window-layout-ready', debouncedUpdateOpenPages);
            ofApp.removeListener('window-view-detached', debouncedUpdateOpenPages);
        };
    }, []);
    return openPages;
};

export default useOpenPages;
