import { useCallback, useContext, useEffect, useLayoutEffect, useMemo } from 'react';

import { SelectableResult } from '@enterprise/components/ControlBar/SearchMenu/ResultsContainerWrapper';

import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';

/**
 * Custom hook for managing keyboard navigation within the search menu.
 * It allows users to navigate through selectable results using keyboard controls.
 *
 * @param focused - The currently focused selectable result.
 * @param setFocused - Function to set the focused result.
 * @param content - Array of selectable results to navigate through.
 * @param onFocus - Callback function to handle focus change.
 * @param sendKeyboardEventToBrowserWindow - Function to send keyboard events to the browser window.
 * @param resultListContainer - Reference to the container holding the results.
 *
 */
const useKeyboardNavigation = (
    focused: SelectableResult | null,
    setFocused: (result: SelectableResult | null) => void,
    content: SelectableResult[] | [],
    onFocus: (result: SelectableResult) => void,
    sendKeyboardEventToBrowserWindow: (event: React.KeyboardEvent) => void,
    resultListContainer: HTMLDivElement | null
) => {
    const { postFocusedChangedAnnouncement } = useContext(SearchMenuControlContext);
    const currentFocusedIndex = useMemo(
        () =>
            content?.findIndex((result: SelectableResult) => {
                if (focused?.type === 'view-more-result' && result.type === 'view-more-result') {
                    return focused.providerId === result.providerId;
                }
                return result === focused;
            }),
        [content, focused]
    );

    useLayoutEffect(() => {
        if (resultListContainer) {
            const children = resultListContainer.childNodes;
            const searchResults = Array.from(children).filter((child) =>
                (child as HTMLElement).classList?.contains('search-result')
            );
            const child = searchResults[currentFocusedIndex] as HTMLDivElement;
            if (!child) return;
            child.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }
    }, [currentFocusedIndex, resultListContainer]);

    const handleArrowDown = useCallback(() => {
        if (currentFocusedIndex < content.length - 1) {
            const next = content[currentFocusedIndex + 1];
            onFocus(next);
            postFocusedChangedAnnouncement(next);
        } else {
            const first = content[0];
            onFocus(first);
            postFocusedChangedAnnouncement(first);
        }
    }, [currentFocusedIndex, content, onFocus, postFocusedChangedAnnouncement]);

    const handleArrowUp = useCallback(() => {
        if (currentFocusedIndex > 0) {
            const prev = content[currentFocusedIndex - 1];
            onFocus(prev);
            postFocusedChangedAnnouncement(prev);
        } else {
            const last = content[content.length - 1];
            onFocus(last);
            postFocusedChangedAnnouncement(last);
        }
    }, [currentFocusedIndex, content, onFocus, postFocusedChangedAnnouncement]);

    const handleHome = useCallback(() => {
        if (content.length) {
            onFocus(content[0]);
            postFocusedChangedAnnouncement(content[0]);
        }
    }, [content, onFocus, postFocusedChangedAnnouncement]);

    const handleEnd = useCallback(() => {
        if (content.length) {
            const lastIndex = content.length - 1;
            onFocus(content[lastIndex]);
            postFocusedChangedAnnouncement(content[lastIndex]);
        }
    }, [content, onFocus, postFocusedChangedAnnouncement]);

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent & React.KeyboardEvent) => {
            switch (event.key) {
                case 'ArrowDown':
                    event.preventDefault();
                    handleArrowDown();
                    break;
                case 'ArrowUp':
                    event.preventDefault();
                    handleArrowUp();
                    break;
                case 'Home':
                    event.preventDefault();
                    handleHome();
                    break;
                case 'End':
                    event.preventDefault();
                    handleEnd();
                    break;
                case 'Shift':
                case 'Tab':
                case 'ArrowLeft':
                case 'ArrowRight':
                case 'Enter':
                    break;
                default:
                    if (!(event.metaKey && event.ctrlKey)) {
                        setFocused(null);
                        sendKeyboardEventToBrowserWindow(event);
                    }
                    break;
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [handleArrowDown, handleArrowUp, handleEnd, handleHome, sendKeyboardEventToBrowserWindow, setFocused]);
};

export default useKeyboardNavigation;
